"""Quién habla en Unity (objetos Dialogue/Character) y repaso de _AutoGeneratedTranslations.txt.
Todo con datos inventados; ningún test abre un juego ni llama a Ollama."""
from __future__ import annotations

import struct
import tempfile
import unittest
from pathlib import Path

from traductor.motores.unity import repasar_xunity
from traductor.personajes import FichaPersonajes, InfoLinea, Personaje, resolver_linea
from traductor.unity_dialogos import (Hablante, TablaHablantes, datos_de_personaje, guardar_tabla,
                                      lineas_de_dialogo)


def _cad(texto: str) -> bytes:
    b = texto.encode("utf-8")
    return struct.pack("<i", len(b)) + b + b"\0" * ((4 - len(b) % 4) % 4)


def _linea(line_id: str, texto: str, speaker: str = "", file_id: int = 0, path_id: int = 0,
           sustituto: str = "") -> bytes:
    return (_cad(line_id) + _cad("") + _cad(texto) + _cad(speaker) + struct.pack("<iq", file_id, path_id)
            + _cad(sustituto) + _cad("pose") + b"\0" * 40)


def _personaje(m_name: str, nombre: str, genero: int, handlers: int = 2) -> bytes:
    cab = b"\0" * 12 + b"\1\0\0\0" + b"\0" * 12
    return cab + _cad(m_name) + _cad(nombre) + b"\1\0\0\0" + struct.pack("<i", handlers) + b"\0" * 12 * handlers \
        + struct.pack("<i", genero) + b"\0" * 16


class TestLecturaDeBytes(unittest.TestCase):
    def test_lineas_de_dialogo(self):
        raw = b"\0" * 28 + _cad("Escena") + struct.pack("<i", 2) \
            + _linea("line_0", "I'm so tired.", file_id=3, path_id=99) + _linea("line_1", "Hi.", speaker="Ana")
        self.assertEqual(list(lineas_de_dialogo(raw)),
                         [("I'm so tired.", "", 3, 99, ""), ("Hi.", "Ana", 0, 0, "")])

    def test_datos_de_personaje(self):
        self.assertEqual(datos_de_personaje(_personaje("Char_Woman", "Woman", 1)), ("Woman", "mujer"))
        self.assertEqual(datos_de_personaje(_personaje("Char_Guard", "Guard", 0, handlers=0)), ("Guard", "hombre"))
        self.assertEqual(datos_de_personaje(_personaje("X", "Robot", 7)), ("Robot", None))


class TestTabla(unittest.TestCase):
    def test_busca_aunque_cambien_las_etiquetas(self):
        t = TablaHablantes({"<i>(I'm so tired…)</i>": Hablante("Ana", "mujer")})
        self.assertEqual(t.info("<i>(I'm so tired…)</i>"), InfoLinea(hablante="Ana", genero="mujer"))
        self.assertEqual(t.info("(I’m so  tired...)"), InfoLinea(hablante="Ana", genero="mujer"))
        self.assertIsNone(t.info("Something else."))

    def test_guardar_y_cargar(self):
        with tempfile.TemporaryDirectory() as tmp:
            ruta = Path(tmp) / "hablantes_unity.json"
            guardar_tabla(ruta, {"Hi.": Hablante("Guard", "hombre"), "Yo.": Hablante("", "mujer")})
            t = TablaHablantes.cargar(ruta)
            self.assertEqual(t.info("Hi."), InfoLinea(hablante="Guard", genero="hombre"))
            self.assertEqual(t.info("Yo."), InfoLinea(hablante=None, genero="mujer"))
            self.assertEqual(len(TablaHablantes.cargar(Path(tmp) / "no_existe.json")), 0)


def _ficha() -> FichaPersonajes:
    return FichaPersonajes(personajes=[Personaje("Ana", "mujer", "protagonista"), Personaje("Max", "neutro")])


class TestGeneroDelJuego(unittest.TestCase):
    def test_extra_que_no_esta_en_la_ficha(self):
        ctx = resolver_linea(_ficha(), "I'm ready.", InfoLinea(hablante="Guard", genero="hombre"))
        self.assertEqual((ctx.hablante.nombre, ctx.hablante.genero), ("Guard", "hombre"))
        self.assertEqual(ctx.destinatario.nombre, "Ana")  # un extra le habla a la protagonista

    def test_manda_la_ficha(self):
        ctx = resolver_linea(_ficha(), "I'm ready.", InfoLinea(hablante="Max", genero="hombre"))
        self.assertEqual(ctx.hablante.genero, "neutro")

    def test_sin_genero_no_se_inventa(self):
        self.assertIsNone(resolver_linea(_ficha(), "I'm ready.", InfoLinea(hablante="Guard")).hablante)


class TraductorFalso:
    """Lo mínimo que usa repasar_xunity."""

    def __init__(self, respuestas: dict[str, str]):
        from traductor.config import Perfil
        self.perfil = Perfil(contexto="CTX", personajes=_ficha())
        self.respuestas = respuestas
        self.pedidas: list[tuple[str, InfoLinea | None]] = []

    def _contexto_linea(self, texto, info=None):
        return resolver_linea(self.perfil.personajes, texto, info)

    def _sentido_mal(self, original, traduccion):
        return False

    def _compatible_con_ficha(self, traduccion, ctx):
        from traductor.ollama import OllamaTranslator
        return OllamaTranslator._compatible_con_ficha(self, traduccion, ctx)

    def translate(self, texto, info=None, lanzar_error=False):
        self.pedidas.append((texto, info))
        return self.respuestas[texto]


class TestRepasoXUnity(unittest.TestCase):
    def test_solo_cambia_lo_que_choca_con_quien_habla(self):
        with tempfile.TemporaryDirectory() as tmp:
            ruta = Path(tmp) / "_AutoGeneratedTranslations.txt"
            contenido = ("I'm so tired.=Estoy muy cansado.\r\n"      # habla Ana (mujer): concordancia, sin modelo
                         "I'm ready.=Estoy lista.\r\n"               # habla Ana: bien, no se toca
                         "Open the door.=Abre la puerta.\r\n"        # sin género
                         "Zoe=Zoe\r\n"                               # un nombre: igual que el original, bien
                         "https://x.com/some_artist=https://x.com/some_artist\r\n"
                         "<color=#EB83FF>Hhh.. Khh-.. Mnh..</color>=<color=#EB83FF>Hhh.. Khh-.. Mnh..</color>\r\n"
                         "Y̵o̶u̵ won't=No lo harás\r\n"  # texto "glitch": no se toca
                         "Let's meet at the old market tonight.=Let's meet at the old market tonight.\r\n")
            ruta.write_bytes(contenido.encode("utf-8"))
            tabla = TablaHablantes({"I'm so tired.": Hablante("Ana", "mujer"),
                                    "I'm ready.": Hablante("Ana", "mujer"),
                                    "Let's meet at the old market tonight.": Hablante("Guard", "hombre")})
            t = TraductorFalso({"Let's meet at the old market tonight.": "Veámonos esta noche en el mercado viejo."})
            stats = repasar_xunity(ruta, t, tabla)
            self.assertEqual(t.pedidas, [("Let's meet at the old market tonight.",
                                          InfoLinea(hablante="Guard", genero="hombre"))])
            esperado = contenido.replace("muy cansado", "muy cansada").replace(
                "=Let's meet at the old market tonight.", "=Veámonos esta noche en el mercado viejo.")
            self.assertEqual(ruta.read_bytes().decode("utf-8"), esperado)
            self.assertEqual((stats["cambios"], stats["concordancia"], stats["retraducidas"]), (2, 1, 1))


if __name__ == "__main__":
    unittest.main()
